/**
 * A asa da borboleta — a cor que não vem de pigmento nenhum.
 *
 * Nas escamas da Morpho há cristas empilhadas a uma distância fixa. A luz branca
 * bate nelas, e só o comprimento de onda que "cabe" nesse espaçamento volta
 * reforçado; o resto se cancela. Moer a asa não solta tinta azul — a cor está na
 * GEOMETRIA, e é por isso que a cena precisa mostrar as cristas e o espaçamento
 * ao mesmo tempo que a cor resultante.
 *
 * O espectro embaixo é a régua: dá para ver o comprimento de onda caminhando do
 * vermelho ao violeta enquanto o slider anda, com a marca do azul no lugar.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Faixa visível desenhada no espectro, em nanômetros. */
const VISIVEL_MIN = 380;
const VISIVEL_MAX = 720;

/**
 * Comprimento de onda → cor, na aproximação clássica de Dan Bruton.
 *
 * Fora do visível a cor não existe: devolve um cinza, que é como o olho lê o
 * infravermelho e o ultravioleta — não lê.
 */
function corDaOnda(nm: number, alfa = 1): string {
  // O slider chega a 156 nm (200 nm × 0,78), bem abaixo do visível. Sem esta
  // porta os ramos de baixo devolveriam canal negativo, `NaN` no `rgb()` — e o
  // canvas ignora cor inválida em silêncio, continuando com a anterior.
  if (!Number.isFinite(nm) || nm < 380 || nm > 780) return `rgb(140 140 150 / ${alfa * 100}%)`;

  let r = 0;
  let g = 0;
  let b = 0;

  if (nm < 440) {
    r = -(nm - 440) / 60;
    b = 1;
  } else if (nm < 490) {
    g = (nm - 440) / 50;
    b = 1;
  } else if (nm < 510) {
    g = 1;
    b = -(nm - 510) / 20;
  } else if (nm < 580) {
    r = (nm - 510) / 70;
    g = 1;
  } else if (nm < 645) {
    r = 1;
    g = -(nm - 645) / 65;
  } else {
    r = 1;
  }

  // O olho perde sensibilidade nas pontas da faixa.
  const forca =
    nm < 420 ? 0.3 + (0.7 * (nm - 380)) / 40 : nm > 700 ? 0.3 + (0.7 * (780 - nm)) / 80 : 1;
  const canal = (v: number): number => Math.round(255 * (limitar(v, 0, 1) * forca) ** 0.8);

  return `rgb(${canal(r)} ${canal(g)} ${canal(b)} / ${alfa * 100}%)`;
}

const difracao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** As cristas da escama, em corte, com o espaçamento que o slider dita. */
  function cristas(
    ctx: CanvasRenderingContext2D,
    x0: number,
    x1: number,
    base: number,
    altura: number,
    espacamento: number,
    tinta: string,
  ): number[] {
    const cor = paleta();
    const picos: number[] = [];

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(x0, base);
    ctx.lineTo(x1, base);
    ctx.stroke();

    for (let x = x0 + espacamento / 2; x <= x1; x += espacamento) {
      picos.push(x);
      const largura = Math.min(espacamento * 0.42, altura * 0.5);
      retangulo(
        ctx,
        x - largura / 2,
        base - altura,
        largura,
        altura,
        largura * 0.3,
        tinta,
        cor.texto,
        1,
      );
    }

    return picos;
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const d = numeroDe(valores, 'd', 600);
    const lambda = numeroDe(info, 'lambda', d * 0.78);
    const ok = info.ok === true;
    const tintaOnda = corDaOnda(lambda);

    titulo(ctx, L, A, 'A cor está na geometria, não no pigmento');

    // ── As cristas e os raios ────────────────────────────────────────────
    const x0 = L * 0.08;
    const x1 = L * 0.62;
    const base = A * 0.56;
    // O espaçamento na tela acompanha `d` (200–800 nm) sem virar caricatura.
    const espacamento = limitar((d / 800) * (x1 - x0) * 0.26, 10, (x1 - x0) * 0.3);
    const alturaCrista = A * 0.13;

    const picos = cristas(ctx, x0, x1, base, alturaCrista, espacamento, cor.trilho);

    // O raio branco que chega.
    const entrada: readonly [number, number] = [x0 + (x1 - x0) * 0.1, A * 0.2];
    const encontro: readonly [number, number] = [(x0 + x1) / 2, base - alturaCrista];

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(entrada[0], entrada[1]);
    ctx.lineTo(encontro[0], encontro[1]);
    ctx.stroke();

    const miudo = limitar(A * 0.03, 8, 11);
    texto(ctx, 'luz branca', entrada[0], entrada[1] - miudo, miudo, { cor: cor.fraco, peso: 700 });

    // O raio que volta, na cor do comprimento de onda reforçado; pulsa devagar.
    const brilho = 0.7 + Math.sin(t * 2) * 0.25;
    ctx.strokeStyle = corDaOnda(lambda, brilho);
    ctx.lineWidth = 3.4;
    ctx.beginPath();
    ctx.moveTo(encontro[0], encontro[1]);
    ctx.lineTo(x1 - (x1 - x0) * 0.06, A * 0.2);
    ctx.stroke();

    // A medida do espaçamento entre duas cristas vizinhas.
    const a = picos[Math.max(0, Math.floor(picos.length / 2) - 1)];
    const b = picos[Math.max(1, Math.floor(picos.length / 2))];
    if (a !== undefined && b !== undefined && b > a) {
      const y = base + miudo * 1.6;
      ctx.strokeStyle = cor.azul;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(a, base);
      ctx.lineTo(a, y + 3);
      ctx.moveTo(b, base);
      ctx.lineTo(b, y + 3);
      ctx.moveTo(a, y);
      ctx.lineTo(b, y);
      ctx.stroke();
      texto(ctx, `d = ${Math.round(d)} nm`, (a + b) / 2, y + miudo * 1.6, miudo, {
        cor: cor.azul,
        peso: 700,
      });
    }

    // ── A asa, pintada com a cor resultante ──────────────────────────────
    const asaX = L * 0.82;
    const asaY = A * 0.4;
    const asaR = Math.min(L * 0.14, A * 0.2);

    ctx.save();
    ctx.fillStyle = tintaOnda;
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.4;
    for (const lado of [-1, 1]) {
      // Asa de cima (maior) e de baixo, o par que faz a silhueta ler como asa.
      ctx.beginPath();
      ctx.ellipse(
        asaX + lado * asaR * 0.55,
        asaY - asaR * 0.25,
        asaR * 0.55,
        asaR * 0.72,
        lado * 0.5,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      ctx.stroke();
      ctx.beginPath();
      ctx.ellipse(
        asaX + lado * asaR * 0.42,
        asaY + asaR * 0.5,
        asaR * 0.4,
        asaR * 0.46,
        lado * 0.35,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      ctx.stroke();
    }
    // O corpo.
    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.ellipse(asaX, asaY + asaR * 0.1, asaR * 0.09, asaR * 0.8, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // ── O espectro ───────────────────────────────────────────────────────
    const ex0 = L * 0.08;
    const ex1 = L * 0.92;
    const ey = A * 0.79;
    const eAltura = limitar(A * 0.05, 9, 15);
    const nmX = (nm: number): number =>
      ex0 +
      ((limitar(nm, VISIVEL_MIN, VISIVEL_MAX) - VISIVEL_MIN) / (VISIVEL_MAX - VISIVEL_MIN)) *
        (ex1 - ex0);

    ctx.save();
    ctx.beginPath();
    ctx.roundRect(ex0, ey, ex1 - ex0, eAltura, eAltura / 3);
    ctx.clip();
    for (let x = ex0; x <= ex1; x += 2) {
      const nm = VISIVEL_MIN + ((x - ex0) / (ex1 - ex0)) * (VISIVEL_MAX - VISIVEL_MIN);
      ctx.fillStyle = corDaOnda(nm);
      ctx.fillRect(x, ey, 3, eAltura);
    }
    ctx.restore();
    retangulo(ctx, ex0, ey, ex1 - ex0, eAltura, eAltura / 3, undefined, cor.trilho, 1);

    // A marca do alvo (o azul da Morpho) e a do valor atual.
    const alvo = 470;
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.6;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(nmX(alvo), ey - 5);
    ctx.lineTo(nmX(alvo), ey + eAltura + 5);
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, `alvo ${alvo}`, nmX(alvo), ey - miudo, miudo, { cor: cor.texto, peso: 700 });

    const marcaX = nmX(lambda);
    ctx.fillStyle = ok ? cor.verde : cor.texto;
    ctx.beginPath();
    ctx.moveTo(marcaX, ey + eAltura + 3);
    ctx.lineTo(marcaX - 5, ey + eAltura + 11);
    ctx.lineTo(marcaX + 5, ey + eAltura + 11);
    ctx.closePath();
    ctx.fill();

    texto(ctx, `λ ≈ ${Math.round(lambda)} nm`, L / 2, A * 0.885, limitar(A * 0.042, 10, 14), {
      cor: ok ? cor.verde : cor.fraco,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'A escama devolve o azul da Morpho ✔',
      lambda > alvo
        ? 'Cristas afastadas demais: a asa volta avermelhada.'
        : 'Cristas juntas demais: a asa passa do azul.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default difracao;
